import { Column, Entity, PrimaryGeneratedColumn } from 'typeorm';

export const QUESTION_TYPES = [
  'MCQ',
  'FILLUPS',
  'SUBJECTIVE',
  'TRUE/FALSE',
] as const;

export type QuestionType = (typeof QUESTION_TYPES)[number];

// Maps the existing `Question` table. QuesID is generated by MySQL.
@Entity({ name: 'Question' })
export class Question {
  @PrimaryGeneratedColumn({ name: 'QuesID', type: 'int' })
  quesId: number;

  @Column({ name: 'QuesText', type: 'text' })
  quesText: string;

  @Column({ name: 'QuesType', type: 'enum', enum: QUESTION_TYPES })
  quesType: QuestionType;

  @Column({ name: 'SourceID', type: 'int' })
  sourceId: number;
}
